/// A student as returned by SimpleStudentApi (`components.schemas.Student`
/// in swagger.json). Field names match the JSON exactly (camelCase).
class Student {
  const Student({
    this.id = 0,
    required this.firstName,
    required this.lastName,
    required this.email,
    required this.studyProgram,
    required this.enrollmentYear,
  });

  /// Generated by the database. 0 means "not saved yet".
  final int id;
  final String firstName;
  final String lastName;
  final String email;
  final String studyProgram;
  final int enrollmentYear;

  String get fullName => '$firstName $lastName';

  /// Initials for the avatar in the list, e.g. "JJ".
  String get initials {
    final f = firstName.isNotEmpty ? firstName[0] : '';
    final l = lastName.isNotEmpty ? lastName[0] : '';
    final result = '$f$l'.toUpperCase();
    return result.isEmpty ? '?' : result;
  }

  factory Student.fromJson(Map<String, dynamic> json) {
    return Student(
      id: (json['id'] as num?)?.toInt() ?? 0,
      firstName: json['firstName'] as String? ?? '',
      lastName: json['lastName'] as String? ?? '',
      email: json['email'] as String? ?? '',
      studyProgram: json['studyProgram'] as String? ?? '',
      enrollmentYear: (json['enrollmentYear'] as num?)?.toInt() ?? 0,
    );
  }

  /// Body for POST / PUT. The API ignores `id` on create.
  Map<String, dynamic> toJson() => {
        'id': id,
        'firstName': firstName,
        'lastName': lastName,
        'email': email,
        'studyProgram': studyProgram,
        'enrollmentYear': enrollmentYear,
      };
}
